public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (b + a <= k) {
        int next = a + b;
        fibs.add(next);
        a = b;
        b = next;
    }

    // Find the minimum number of Fibonacci numbers whose sum is equal to k
    int result = 0;
    int index = fibs.size() - 1;
    while (k > 0) {
        if (fibs.get(index) <= k) {
            k -= fibs.get(index);
            result++;
        }
        index--;
    }
    return result;
}

